class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses patch (partial update) by default instead of
        // replace (full document write). Existing sync logic that reads-then-saves
        // full documents should opt into replace to avoid subtle data-loss bugs
        // when concurrent writers touch different properties.
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();

        // NOTE on raw SQL: any query using  WHERE c.Discriminator = 'Blog'
        // will continue to work because we kept the old discriminator property
        // name via HasDiscriminator<string>("Discriminator") above.
        // Without that fix, EF 9 would write "$type" and old queries would
        // return zero results.
    }
}

